# Message Translator: CSV -> kanonisch
def translate(zeile):
    typ, nr, betrag = zeile.split(";")
    return {"typ": typ, "nr": nr,
            "betrag": float(betrag)}

ziele = {"rechnung": [], "gutschrift": [],
         "dead_letter": []}

# Content-Based Router
def route(zeile):
    try:
        m = translate(zeile)
    except ValueError:      # kaputt
        m = None
    if m is None or m["typ"] not in \
            ("rechnung", "gutschrift"):
        ziele["dead_letter"].append(zeile)
    else:
        ziele[m["typ"]].append(m["nr"])

for z in ["rechnung;R1;120.50",
          "gutschrift;G1;20",
          "mahnung;M1;5",
          "rechnung;R2;abc"]:
    route(z)
for k, v in ziele.items():
    print(k, v)

# Ausgabe:
# rechnung ['R1']
# gutschrift ['G1']
# dead_letter ['mahnung;M1;5', 'rechnung;R2;abc']
